CREATE TABLE market_quotes (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), document_version_id TEXT REFERENCES document_versions(id), supplier_name TEXT, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE market_quote_items (id TEXT PRIMARY KEY NOT NULL, quote_id TEXT NOT NULL REFERENCES market_quotes(id), description TEXT NOT NULL, quantity TEXT NOT NULL, unit_value TEXT, exclusion_reason TEXT);
CREATE TABLE market_analyses (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), document_version_id TEXT REFERENCES document_versions(id), status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE budget_certificates (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), document_version_id TEXT REFERENCES document_versions(id), status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE precontractual_packages (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), kind TEXT NOT NULL, document_version_id TEXT REFERENCES document_versions(id), status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE offers (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), document_version_id TEXT REFERENCES document_versions(id), intake_method TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE evaluations (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), document_version_id TEXT REFERENCES document_versions(id), status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE evaluation_committee_actions (id TEXT PRIMARY KEY NOT NULL, evaluation_id TEXT NOT NULL REFERENCES evaluations(id), actor_user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE selection_decisions (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), document_version_id TEXT REFERENCES document_versions(id), rector_user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE formalizations (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), document_version_id TEXT REFERENCES document_versions(id), status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE execution_records (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), document_version_id TEXT REFERENCES document_versions(id), kind TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE closure_records (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), document_version_id TEXT REFERENCES document_versions(id), status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX market_quotes_process_idx ON market_quotes(process_id); CREATE INDEX offers_process_idx ON offers(process_id); CREATE INDEX evaluations_process_idx ON evaluations(process_id); CREATE INDEX execution_records_process_idx ON execution_records(process_id);
